import re

PAIR = re.compile(r"^(?P<key>[A-Za-z_][\w]*)=(?P<value>.*)$")
ESC = {"\\s": " ", "\\p": "|", "\\/": "/", "\\\\": "\\", "\\a": "\a", "\\b": "\b", "\\f": "\f",
       "\\n": "\n", "\\r": "\r", "\\t": "\t", "\\v": "\v"}
UNESC = re.compile(r"\\[spabfnrtv/\\]")


def unescape(v):
    # ServerQuery escapes: \s space, \p pipe, \/ slash, \\ backslash
    return UNESC.sub(lambda m: ESC[m.group(0)], v)


def record(text):
    rec = {}
    for tok in text.split(" "):
        if not tok:
            continue
        m = PAIR.match(tok)
        if m:
            rec[m.group("key")] = unescape(m.group("value"))
        else:
            rec[tok] = ""
    return rec


def parse(lines):
    clients, cols, used_c = [], [], []
    result, used_r = [], []
    for j, ln in enumerate(lines):
        ln = ln.strip()
        if not ln:
            continue
        if ln.startswith("error "):
            rec = record(ln[6:])
            if "id" in rec:
                rec = {"error id": rec.pop("id"), **rec}
            result.append(rec)
            used_r.append(j)
            continue
        if "=" not in ln:
            continue
        for part in ln.split("|"):
            rec = record(part)
            for k in rec:
                if k not in cols:
                    cols.append(k)
            clients.append(rec)
        used_c.append(j)
    clients = [{k: r.get(k, "") for k in cols} for r in clients]
    return [{"name": "clients", "kind": "table", "lines": used_c, "records": clients},
            {"name": "result", "kind": "kv", "lines": used_r, "records": result}]
